# Completa la línea marcada y compruébala con py check.
def sin_fijar(lineas):
    malas = []
    for l in lineas:
        l = l.strip()
        if l == "" or l.startswith("#"):
            continue
        # ← añade aquí: si la línea no tiene «==», guarda su nombre
    return malas

print(sin_fijar(["numpy==2.5.4", "requests", "# comentario"]))   # ['requests']
